"""Downloadable products assembled only from explicit immutable artifact snapshots.

Packaging proves file integrity and layout, not that a product works. No workspace
code is executed here and no unpublished/private file is discovered implicitly.
"""
import hashlib
import io
import json
import re
import time
import uuid
import unicodedata
import zipfile


class DeliveryError(ValueError):
    code = 'delivery'


RESERVED = {'delivery.json', 'run.txt'}

def _path_key(value):
    # Common filesystems normalize Unicode and/or compare names without case.
    return unicodedata.normalize('NFC', value.casefold())


def _path(value):
    if (not isinstance(value, str) or not value or len(value) > 240
            or any(ord(c) < 32 or ord(c) == 127 for c in value)
            or any(c in value for c in '\\:<>"|?*')):
        raise DeliveryError('Delivery paths must be portable relative file paths.')
    try:
        value.encode('utf-8')
    except UnicodeEncodeError:
        raise DeliveryError('Delivery paths must be valid UTF-8.') from None
    parts = value.split('/')
    if any(not p or p.startswith('.') or p.endswith((' ', '.')) for p in parts):
        raise DeliveryError('Hidden, empty and parent path segments are forbidden.')
    if any(re.fullmatch(r'(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\..*)?', p, re.I) for p in parts):
        raise DeliveryError('Reserved device names are forbidden in delivery paths.')
    if parts[0].casefold() in RESERVED:
        raise DeliveryError('DELIVERY.json and RUN.txt are generated by the server.')
    return value


def _instructions(value):
    if not isinstance(value, str) or not value.strip() or len(value) > 6000 or '\0' in value:
        raise DeliveryError('Provide nonempty run instructions, at most 6000 characters, without NUL.')
    try:
        value.encode('utf-8')
    except UnicodeEncodeError:
        raise DeliveryError('Run instructions must be valid UTF-8.') from None
    return value.strip()


def _snapshot(run, store, artifact_id):
    item = next((a for a in run.get('artifacts', []) if a.get('id') == artifact_id), None)
    if item is None:
        raise DeliveryError('Delivery references an artifact outside this run.')
    snapshot = store.get(artifact_id)
    if any(snapshot.get(k) != item.get(k) for k in
           ('id', 'runId', 'taskId', 'ownerAgentId', 'path', 'sha256', 'size')):
        raise DeliveryError('Published artifact metadata changed.')
    if snapshot.get('runId') != run['id']:
        raise DeliveryError('Cross-run delivery is forbidden; use authorized inherited snapshots.')
    content = snapshot.get('content')
    if not isinstance(content, str) or not content.strip():
        raise DeliveryError('A delivery file must have nonempty published text.')
    raw = content.encode('utf-8')
    if len(raw) != snapshot.get('size') or hashlib.sha256(raw).hexdigest() != snapshot.get('sha256'):
        raise DeliveryError('Published artifact content failed its SHA256/size check.')
    _path(snapshot['path'])
    return snapshot


def _current_source(run, snapshot):
    # An inherited snapshot can be superseded by a newly published file too.
    # Check the current logical path before accepting its historical provenance.
    latest = next((a for a in reversed(run.get('artifacts', []))
                   if _path_key(a.get('path', '')) == _path_key(snapshot['path'])
                   and a.get('ownerAgentId') == snapshot.get('ownerAgentId')), None)
    if not latest or latest['id'] != snapshot['id']:
        raise DeliveryError('Select the latest published revision of each source file.')
    if snapshot.get('sourceRunId'):
        return None
    task = next((t for t in run.get('steps', []) if t.get('id') == snapshot.get('taskId')), None)
    if not task or snapshot['id'] not in task.get('outputs', []):
        raise DeliveryError('Delivery file is no longer an output of its source task.')
    return task


def create_delivery(run, task, store, artifact_ids, entrypoint, instructions):
    if (not isinstance(artifact_ids, list) or not 1 <= len(artifact_ids) <= 40
            or any(not isinstance(a, str) for a in artifact_ids)
            or len(set(artifact_ids)) != len(artifact_ids)):
        raise DeliveryError('Select 1–40 distinct real artifact IDs.')
    entrypoint = _path(entrypoint)
    instructions = _instructions(instructions)
    snapshots, paths, files = [], set(), []
    for artifact_id in artifact_ids:
        snapshot = _snapshot(run, store, artifact_id)
        if not store.can_access(artifact_id, task['agentId'], run['id']):
            raise DeliveryError('This task has no explicit access to a selected artifact.')
        key = _path_key(snapshot['path'])
        if key in paths:
            raise DeliveryError('Two selected artifacts collide at the same product path.')
        if any(key.startswith(p + '/') or p.startswith(key + '/') for p in paths):
            raise DeliveryError('Delivery paths contain a file/directory collision.')
        paths.add(key)
        source = _current_source(run, snapshot)
        snapshots.append(snapshot)
        files.append({'artifactId': artifact_id, 'path': snapshot['path'],
                      'sha256': snapshot['sha256'], 'size': snapshot['size'],
                      'sourceTaskId': snapshot.get('taskId'),
                      'sourceRevision': source.get('revision', 0) if source else None,
                      'inherited': bool(snapshot.get('sourceRunId'))})
    if entrypoint not in [s['path'] for s in snapshots]:
        raise DeliveryError('The entrypoint must be one of the selected published files.')
    if all(s.get('sourceRunId') for s in snapshots):
        raise DeliveryError('A new delivery cannot consist solely of unchanged inherited files.')
    if sum(s['size'] for s in snapshots) > 4 * 1024 * 1024:
        raise DeliveryError('Delivery exceeds the 4 MiB text quota.')
    return {'id': 'delivery-' + uuid.uuid4().hex, 'version': 1, 'runId': run['id'],
            'taskId': task['id'], 'taskRevision': task.get('revision', 0),
            'agentId': task['agentId'], 'createdAt': int(time.time() * 1000),
            'entrypoint': entrypoint, 'instructions': instructions.strip(), 'files': files,
            'status': 'packaged', 'semanticQuality': 'unassessed'}


def validate_delivery(delivery, run, store, current=True):
    if not isinstance(delivery, dict) or delivery.get('runId') != run.get('id'):
        raise DeliveryError('Delivery belongs to a different run.')
    files = delivery.get('files')
    if not isinstance(files, list) or not 1 <= len(files) <= 40:
        raise DeliveryError('Delivery manifest is missing its bounded file list.')
    task = next((t for t in run.get('steps', []) if t.get('id') == delivery.get('taskId')), None)
    if (not task or task.get('agentId') != delivery.get('agentId')
            or (current and task.get('revision', 0) != delivery.get('taskRevision'))):
        raise DeliveryError('Delivery is no longer bound to the current task revision.')
    seen, snapshots = set(), []
    for item in files:
        if not isinstance(item, dict):
            raise DeliveryError('Invalid file manifest.')
        snapshot = _snapshot(run, store, item.get('artifactId'))
        if any(item.get(k) != snapshot.get(k) for k in ('path', 'sha256', 'size')):
            raise DeliveryError('Delivery manifest no longer matches its immutable file.')
        key = _path_key(_path(item['path']))
        if key in seen or any(key.startswith(p + '/') or p.startswith(key + '/') for p in seen):
            raise DeliveryError('Delivery file paths collide.')
        seen.add(key)
        if current:
            source = _current_source(run, snapshot)
            if source and source.get('revision', 0) != item.get('sourceRevision'):
                raise DeliveryError('A source task changed after this delivery was packaged.')
        snapshots.append(snapshot)
    if delivery.get('entrypoint') not in [s['path'] for s in snapshots]:
        raise DeliveryError('Delivery entrypoint is missing.')
    if sum(s['size'] for s in snapshots) > 4 * 1024 * 1024:
        raise DeliveryError('Delivery exceeds its byte quota.')
    _instructions(delivery.get('instructions'))
    return snapshots


def delivery_zip(delivery, run, store):
    # Old bundles remain downloadable as historical immutable snapshots; they
    # cannot satisfy a new/current task's delivery contract after source changes.
    snapshots = validate_delivery(delivery, run, store, current=False)
    output = io.BytesIO()
    with zipfile.ZipFile(output, 'w', zipfile.ZIP_DEFLATED) as archive:
        for snapshot in snapshots:
            archive.writestr(snapshot['path'], snapshot['content'].encode('utf-8'))
        archive.writestr('RUN.txt', delivery['instructions'].encode('utf-8'))
        archive.writestr('DELIVERY.json', json.dumps(delivery, ensure_ascii=False, indent=2).encode('utf-8'))
    return output.getvalue()
